CREATE TABLE templates (
	id VARCHAR NOT NULL, 
	owner_id VARCHAR NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description VARCHAR(500), 
	category VARCHAR(50), 
	price INTEGER, 
	downloads INTEGER, 
	revenue INTEGER, 
	rating FLOAT, 
	reviews_count INTEGER, 
	status VARCHAR(9), 
	blocks_data JSON, 
	tags JSON, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id)
);

CREATE TABLE workspaces (
	id VARCHAR NOT NULL, 
	owner_id VARCHAR NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	description VARCHAR(500), 
	blocks_data JSON, 
	order_index INTEGER, 
	is_active BOOLEAN, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id)
);

INSERT INTO workspaces (id, owner_id, name, description, blocks_data, order_index, is_active, created_at, updated_at) VALUES ('d1a3fc5a-d7a7-4341-98cc-694393de6dca', 'ae9b3522-cf90-4a64-9adb-69cf0df288d0', '네이버 검색 후 다음 사이트 캡처', NULL, '[]', 0, 1, '2026-03-30 23:05:56.630276', '2026-04-06 02:44:04.091076');

CREATE TABLE videos (
	id VARCHAR NOT NULL, 
	owner_id VARCHAR NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	original_filename VARCHAR(255) NOT NULL, 
	file_path VARCHAR(500) NOT NULL, 
	file_size INTEGER NOT NULL, 
	duration INTEGER, 
	status VARCHAR(50), 
	progress INTEGER, 
	error_message TEXT, 
	audio_path VARCHAR(500), 
	transcript TEXT, 
	frame_count INTEGER, 
	frames_dir VARCHAR(500), 
	analysis_result JSON, 
	generated_blocks JSON, 
	created_at DATETIME, 
	updated_at DATETIME, 
	completed_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id)
);

