CREATE TABLE purchases (
	id VARCHAR NOT NULL, 
	buyer_id VARCHAR NOT NULL, 
	item_id VARCHAR NOT NULL, 
	item_name VARCHAR NOT NULL, 
	item_creator VARCHAR NOT NULL, 
	price INTEGER NOT NULL, 
	status VARCHAR(9), 
	deadline DATETIME, 
	purchased_at DATETIME, 
	confirmed_at DATETIME, 
	cancelled_at DATETIME, payment_id TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(buyer_id) REFERENCES users (id), 
	FOREIGN KEY(item_id) REFERENCES marketplace_items (id)
);

INSERT INTO purchases (id, buyer_id, item_id, item_name, item_creator, price, status, deadline, purchased_at, confirmed_at, cancelled_at, payment_id) VALUES ('624e273b-693f-4ea7-80d7-f73d58f3940e', 'ae9b3522-cf90-4a64-9adb-69cf0df288d0', 'fed81934-db40-44d5-ae74-482ccc59d2c8', '네이버 검색 후 다음 사이트 캡처', '김도연', 9900, 'ACTIVE', '2026-04-05 02:17:19.720447', '2026-04-02 02:17:19.726598', NULL, NULL, 'payment-1775096207720-mlc3ou1qf');

CREATE TABLE reviews (
	id VARCHAR NOT NULL, 
	user_id VARCHAR NOT NULL, 
	item_id VARCHAR NOT NULL, 
	purchase_id VARCHAR NOT NULL, 
	rating INTEGER NOT NULL, 
	text TEXT NOT NULL, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(item_id) REFERENCES marketplace_items (id), 
	FOREIGN KEY(purchase_id) REFERENCES purchases (id)
);

